import React from 'react';
import { interpolate, spring, useCurrentFrame, useVideoConfig } from 'remotion';
import * as LucideIcons from 'lucide-react';

export interface LogoShineBadge16x9Props {
  logoText?: string;
  iconName?: string;
  imageUrl?: string;
  badgeBgColor?: string;
  badgeBgGradEnd?: string;
  badgeBorderColor?: string;
  logoColor?: string;
  sheenColor?: string;
  glowColor?: string;
  sheenAngle?: number;
  sheenWidth?: number;
  sheenFrequency?: number;
  size?: number;
  animation?: 'spring-pop' | 'smooth-fade' | 'cyber-drop';
  durationFrames?: number;
  delayFrames?: number;
  scale?: number;
  className?: string;
}

export const LogoShineBadge16x9: React.FC<LogoShineBadge16x9Props> = ({
  logoText = 'Pr',
  iconName = '',
  imageUrl = '',
  badgeBgColor = '#00005c',
  badgeBgGradEnd = '#000028',
  badgeBorderColor = '#3b3bcf',
  logoColor = '#9999ff',
  sheenColor = '#ffffff',
  glowColor = '#4b4bff',
  sheenAngle = -25,
  sheenWidth = 110,
  sheenFrequency = 3,
  size = 320,
  animation = 'spring-pop',
  durationFrames,
  delayFrames = 0,
  scale = 1.0,
  className = '',
}) => {
  let frame = 0;
  let fps = 30;
  let compositionDuration = 300;

  try {
    const vConfig = useVideoConfig();
    fps = vConfig.fps || 30;
    compositionDuration = vConfig.durationInFrames || 300;
  } catch (_) {}

  try {
    frame = useCurrentFrame();
  } catch (_) {}

  const totalDuration = Number(durationFrames) || compositionDuration;
  const activeDuration = Math.max(1, totalDuration - Number(delayFrames || 0));
  const currentFrame = Math.max(0, frame - Number(delayFrames || 0));

  // Фазы: Вход -> Парение и циклический блик -> Выход
  const entranceEnd = Math.min(28, Math.floor(activeDuration * 0.16));
  const exitStart = Math.max(entranceEnd + 30, activeDuration - Math.min(32, Math.floor(activeDuration * 0.16)));

  const entranceSpring = spring({
    frame: currentFrame,
    fps,
    config: animation === 'cyber-drop'
      ? { stiffness: 220, damping: 12, mass: 0.9 }
      : { stiffness: 160, damping: 14, mass: 0.8 },
  });

  const exitProgress = interpolate(
    currentFrame,
    [exitStart, activeDuration],
    [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  const floatFactor = interpolate(
    currentFrame,
    [entranceEnd, entranceEnd + 15, exitStart - 10, exitStart],
    [0, 1, 1, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  // 3D микропарение
  const levitateY = Math.sin(currentFrame * 0.08) * 6 * floatFactor;
  const tiltZ = Math.sin(currentFrame * 0.06) * 1.5 * floatFactor;
  const tiltX = Math.cos(currentFrame * 0.07) * 2.5 * floatFactor;

  // Расчет прохода светового блика (Shine Sweep)
  const freq = Math.max(1, Number(sheenFrequency) || 3);
  const cycleDuration = activeDuration / freq;
  const localCycleFrame = currentFrame % cycleDuration;

  // Длительность одного пролета блика
  const sweepActiveDuration = Math.min(cycleDuration * 0.75, 45);
  const sweepLinear = interpolate(
    localCycleFrame,
    [0, sweepActiveDuration],
    [0, 1],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );
  // Плавное ускорение и замедление луча (Bézier S-curve)
  const sweepSmooth = Math.sin((sweepLinear - 0.5) * Math.PI) * 0.5 + 0.5;
  const sweepOffsetPercent = interpolate(
    sweepSmooth,
    [0, 1],
    [-130, 230],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );

  // Опциональная иконка Lucide
  const ResolvedIcon = iconName ? (LucideIcons as any)[iconName] : null;

  const badgeSize = Number(size) || 320;
  const borderRadius = Math.round(badgeSize * 0.26);
  const badgeScale = entranceSpring * (1 - exitProgress * 0.3) * Number(scale || 1);
  const badgeOpacity = Math.min(1, entranceSpring * 2.5) * (1 - exitProgress);

  return (
    <div className={`relative flex items-center justify-center select-none bg-transparent ${className}`}>
      <div
        className="relative flex items-center justify-center"
        style={{
          perspective: '1000px',
          transform: `translateY(${levitateY}px) scale(${badgeScale})`,
          opacity: badgeOpacity,
        }}
      >
        {/* Фоновый ореол свечения */}
        <div
          className="absolute pointer-events-none rounded-full transition-all"
          style={{
            width: `${badgeSize + 120}px`,
            height: `${badgeSize + 120}px`,
            filter: 'blur(65px)',
            opacity: (0.65 + Math.sin(currentFrame * 0.08) * 0.15) * (1 - exitProgress),
            background: `radial-gradient(circle, ${glowColor} 0%, rgba(0, 0, 92, 0.4) 55%, transparent 75%)`,
          }}
        />

        {/* Корпус бейджа с 3D-наклоном */}
        <div
          className="relative overflow-hidden border shadow-2xl flex items-center justify-center will-change-transform"
          style={{
            width: `${badgeSize}px`,
            height: `${badgeSize}px`,
            borderRadius: `${borderRadius}px`,
            background: `linear-gradient(145deg, ${badgeBgColor} 0%, ${badgeBgGradEnd} 100%)`,
            borderColor: badgeBorderColor,
            boxShadow: `0 24px 50px rgba(0, 0, 0, 0.65), inset 0 2px 4px rgba(255, 255, 255, 0.3), 0 0 35px ${glowColor}40`,
            transform: `rotateX(${tiltX}deg) rotateZ(${tiltZ}deg)`,
            transformStyle: 'preserve-3d',
          }}
        >
          {/* Внутренний глубокий градиент */}
          <div className="absolute inset-0 bg-gradient-to-br from-white/10 via-transparent to-black/50 pointer-events-none" />

          {/* Контент: Текст / Иконка / Картинка */}
          <div className="relative z-10 flex items-center justify-center select-none">
            {imageUrl ? (
              <img
                src={imageUrl}
                alt="logo"
                className="w-3/4 h-3/4 object-contain pointer-events-none drop-shadow-[0_4px_16px_rgba(0,0,0,0.6)]"
              />
            ) : ResolvedIcon ? (
              <div style={{ color: logoColor }}>
                <ResolvedIcon
                  size={Math.round(badgeSize * 0.55)}
                  strokeWidth={2.4}
                  className="drop-shadow-[0_4px_16px_rgba(0,0,0,0.6)]"
                />
              </div>
            ) : (
              <span
                className="font-black tracking-tight drop-shadow-[0_6px_20px_rgba(0,0,0,0.7)]"
                style={{
                  fontFamily: "-apple-system, BlinkMacSystemFont, 'Montserrat', 'SF Pro Display', sans-serif",
                  fontSize: `${Math.round(badgeSize * 0.44)}px`,
                  color: logoColor,
                  lineHeight: 1,
                }}
              >
                {logoText}
              </span>
            )}
          </div>

          {/* 1. ГЛАВНЫЙ СВЕТОВОЙ БЛИК (Premiere Pro Style CC Light Sweep) */}
          <div
            className="absolute inset-0 pointer-events-none z-20 overflow-hidden"
            style={{
              borderRadius: `${borderRadius}px`,
            }}
          >
            <div
              className="absolute inset-y-[-50%] will-change-transform"
              style={{
                width: `${sheenWidth}px`,
                left: `${sweepOffsetPercent}%`,
                transform: `rotate(${sheenAngle}deg)`,
                background: `linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.15) 20%, ${sheenColor} 50%, rgba(255, 255, 255, 0.15) 80%, transparent 100%)`,
                filter: 'blur(4px)',
                opacity: 0.95,
                mixBlendMode: 'screen',
              }}
            />

            {/* Вторичный мягкий рассеянный ореол блика (Feathered ambient sweep) */}
            <div
              className="absolute inset-y-[-50%] will-change-transform"
              style={{
                width: `${sheenWidth * 2.2}px`,
                left: `${sweepOffsetPercent - 15}%`,
                transform: `rotate(${sheenAngle}deg)`,
                background: `linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.1) 30%, rgba(255, 255, 255, 0.35) 50%, rgba(255, 255, 255, 0.1) 70%, transparent 100%)`,
                filter: 'blur(16px)',
                opacity: 0.75,
                mixBlendMode: 'screen',
              }}
            />
          </div>

          {/* Верхняя световая фаска бейджа */}
          <div className="absolute top-0 inset-x-0 h-[2px] bg-gradient-to-r from-transparent via-white/80 to-transparent z-30 pointer-events-none" />
        </div>
      </div>
    </div>
  );
};

